from collections import deque

def topological_order(deps):
    nodes = set(deps) | {d for ds in deps.values() for d in ds}
    indegree = {n: 0 for n in nodes}
    children = {n: [] for n in nodes}
    for task, requires in deps.items():
        for r in requires:
            children[r].append(task)
            indegree[task] += 1
    queue = deque(sorted(n for n in nodes if indegree[n] == 0))
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for c in sorted(children[n]):
            indegree[c] -= 1
            if indegree[c] == 0:
                queue.append(c)
    return order if len(order) == len(nodes) else None
```

Kahn's algorithm repeatedly takes tasks with no unmet prerequisites. If some tasks are never freed, they form a cycle. This is how build tools order work.

